"""
M02 - A.7.4 Chat luong du lieu.
Quy tac: product/matching.py doc thuoc tinh KHONG nam trong danh sach cho
phep o INTERFACE.md muc 7 (10 thuoc tinh: ride.vehicle_type, ride.pickup_lat,
ride.pickup_lon, driver.status, driver.vehicle_type, driver.lat, driver.lon,
driver.trips_today, driver.acceptance_rate, driver.driver_id).

Phuong phap: phan tich tinh bang ast.parse (KHONG doc code bang mat).
Heuristic theo doi bien:
  - ride_vars: seed = {"ride"} (ten tham so co dinh theo chu ky ham trong
    INTERFACE.md `match(ride, drivers, config, logger=None)`), cong moi
    bien duoc gan truc tiep tu mot ten trong ride_vars (alias don gian).
  - driver_vars: seed = moi bien dich (target) trong vong `for X in drivers`
    (drivers la tham so co dinh), cong alias don gian, cong fallback: bien
    co ten chua "driver" (khong phan biet hoa/thuong) duoc dung nhu mot
    dict (bi subscript/.get).
Bat ky Subscript[string] hoac .get("...") tren cac bien nay voi khoa KHONG
nam trong danh sach cho phep -> flag.
Cac truy cap dong (getattr, **ride, ride.items()/.keys()/.values(),
vars(ride)) khong the xac minh day du bang AST tinh -> CAN NGUOI XEM rieng,
khong tu suy ra DAT.
"""
import ast
from common import make_result, ev, parse_ast, RIDE_ALLOWED, DRIVER_ALLOWED, repo_path

TARGET_FILE = "matching.py"


def _const_str(node):
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value
    return None


def _base_name(node):
    """Lay ten Name goc cua mot Subscript/Attribute value, neu co."""
    if isinstance(node, ast.Name):
        return node.id
    return None


def check(ctx):
    rid = "M02"
    commit = ctx["commit"]
    audit_log = ctx["audit_log"]
    path = repo_path("product", TARGET_FILE)

    tree, src_lines, err = parse_ast(path)
    n0 = audit_log.log(rid, "parse", {"file": TARGET_FILE, "error": err})
    if err or tree is None:
        return make_result(
            rid, "CẦN NGƯỜI XEM",
            [ev(audit_log.path, n0, commit)],
            f"[Chưa xác minh] Không phân tích được {TARGET_FILE} bằng ast.parse: {err}",
        )

    ride_vars = {"ride"}
    driver_vars = set()

    # Pass 1: seed driver_vars tu for-loop lap tren bien ten "drivers"
    for node in ast.walk(tree):
        if isinstance(node, ast.For):
            it = node.iter
            if isinstance(it, ast.Name) and it.id == "drivers":
                if isinstance(node.target, ast.Name):
                    driver_vars.add(node.target.id)

    # Pass 2: alias don gian "x = ride" / "x = <bien driver da biet>" , lap
    # vai lan de bat chuoi alias ngan.
    for _ in range(3):
        for node in ast.walk(tree):
            if isinstance(node, ast.Assign) and len(node.targets) == 1:
                tgt = node.targets[0]
                if isinstance(tgt, ast.Name) and isinstance(node.value, ast.Name):
                    src_name = node.value.id
                    if src_name in ride_vars:
                        ride_vars.add(tgt.id)
                    if src_name in driver_vars:
                        driver_vars.add(tgt.id)

    # Fallback heuristic: bien co ten chua "driver" (ca-insensitive) coi la
    # driver_vars de khong bo sot (nguyen tac bat doi xung: nghi ngo -> xet).
    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and "driver" in node.id.lower() and node.id != "drivers":
            driver_vars.add(node.id)

    findings = []       # (lineno, var, key, obj_kind)
    dynamic_hits = []    # (lineno, mo ta) - truy cap dong khong xac minh duoc

    for node in ast.walk(tree):
        if isinstance(node, ast.Subscript):
            base = _base_name(node.value)
            key = None
            sl = node.slice
            # py3.9+: slice la truc tiep node (khong Index wrapper)
            key = _const_str(sl)
            if base and key is not None:
                if base in ride_vars and key not in RIDE_ALLOWED:
                    findings.append((node.lineno, base, key, "ride"))
                elif base in driver_vars and key not in DRIVER_ALLOWED:
                    findings.append((node.lineno, base, key, "driver"))
        elif isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            attr = node.func.attr
            base = _base_name(node.func.value)
            if attr == "get" and base and node.args:
                key = _const_str(node.args[0])
                if key is not None:
                    if base in ride_vars and key not in RIDE_ALLOWED:
                        findings.append((node.lineno, base, key, "ride"))
                    elif base in driver_vars and key not in DRIVER_ALLOWED:
                        findings.append((node.lineno, base, key, "driver"))
            elif attr in ("items", "keys", "values") and base in (ride_vars | driver_vars):
                dynamic_hits.append((node.lineno, f"{base}.{attr}() - duyet dong, AST tinh khong liet ke het khoa"))
        elif isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "getattr":
            if node.args and _base_name(node.args[0]) in (ride_vars | driver_vars):
                dynamic_hits.append((node.lineno, "getattr(...) tren bien ride/driver - truy cap dong"))

    evidence = []
    for lineno, base, key, kind in findings:
        evidence.append(ev(path, lineno, commit))
        audit_log.log(rid, "forbidden_attr", {"line": lineno, "var": base, "key": key, "kind": kind})

    for lineno, desc in dynamic_hits:
        audit_log.log(rid, "dynamic_access", {"line": lineno, "desc": desc})

    n_scan = audit_log.log(
        rid, "scan_summary",
        {
            "file": TARGET_FILE, "ride_vars": sorted(ride_vars), "driver_vars": sorted(driver_vars),
            "n_findings": len(findings), "n_dynamic": len(dynamic_hits),
        },
    )
    evidence.append(ev(audit_log.path, n_scan, commit))

    if findings:
        detail = "; ".join(f"{base}['{key}'] (dòng {lineno}, nhóm {kind})" for lineno, base, key, kind in findings)
        return make_result(
            rid, "KHÔNG ĐẠT", evidence,
            f"ast.parse product/matching.py: phát hiện {len(findings)} truy cập thuộc tính ngoài danh sách "
            f"cho phép ở INTERFACE.md §7: {detail}. Biến ride={sorted(ride_vars)}, driver={sorted(driver_vars)}.",
        )

    if dynamic_hits:
        detail = "; ".join(f"dòng {ln}: {d}" for ln, d in dynamic_hits)
        return make_result(
            rid, "CẦN NGƯỜI XEM", evidence,
            f"Không tìm thấy truy cập Subscript/.get() sai phép, nhưng có {len(dynamic_hits)} truy cập động "
            f"(getattr/.items()/.keys()/.values()) mà AST tĩnh không liệt kê hết được khóa thực tế: {detail}. "
            f"Theo nguyên tắc bất đối xứng, không suy ra ĐẠT khi còn truy cập không xác minh được.",
        )

    return make_result(
        rid, "ĐẠT", evidence,
        f"Quét toàn bộ product/matching.py bằng ast.parse (mọi Subscript[string] và .get(\"...\") trên biến "
        f"suy ra là ride={sorted(ride_vars)} hoặc driver={sorted(driver_vars)}); không có truy cập nằm ngoài "
        f"danh sách cho phép ở INTERFACE.md §7, và không có truy cập động không xác minh được.",
    )

auditor/rules/m05_hardcoded_constants.py:
"""
M05 - A.6.2.3 Tai lieu thiet ke.
Quy tac: Hang so so hoc nghiep vu trong code khong co trong config.

Phuong phap (AST): quet product/matching.py va product/pricing.py, lay
moi ast.Constant kieu int/float (loai bool, loai {-1,0,1,2} vi thuong la
chi so/buoc lap/trivial), roi doi chieu voi tap gia tri so (duyet de quy)
lay tu product/config/matching.json, pricing.json, mock_data.json.
Hang so khong khop bat ky gia tri config nao -> flag "co kha nang hardcode".

Day la heuristic (co the trung voi gia tri config ngau nhien, hoac la
chi so mang khong phai hang so nghiep vu) -> ket qua toi da CAN NGUOI XEM,
khong tu ket luan KHONG DAT.
"""
import ast
from common import make_result, ev, parse_ast, repo_path

CODE_FILES = [
    ("product/matching.py", repo_path("product", "matching.py")),
    ("product/pricing.py", repo_path("product", "pricing.py")),
]
CONFIG_FILES = [
    repo_path("product", "config", "matching.json"),
    repo_path("product", "config", "pricing.json"),
    repo_path("product", "config", "mock_data.json"),
]
TRIVIAL = {-1, 0, 1, 2}


def _flatten_numbers(obj, out):
    if isinstance(obj, bool):
        return
    if isinstance(obj, (int, float)):
        out.add(obj)
    elif isinstance(obj, dict):
        for v in obj.values():
            _flatten_numbers(v, out)
    elif isinstance(obj, list):
        for v in obj:
            _flatten_numbers(v, out)


def check(ctx):
    rid = "M05"
    commit = ctx["commit"]
    audit_log = ctx["audit_log"]
    import json

    config_numbers = set()
    config_scanned = []
    config_missing = []
    for p in CONFIG_FILES:
        try:
            with open(p, "r", encoding="utf-8") as f:
                data = json.load(f)
            _flatten_numbers(data, config_numbers)
            config_scanned.append(p)
        except Exception as e:
            config_missing.append((p, str(e)))
            audit_log.log(rid, "config_error", {"file": p, "error": str(e)})

    evidence = []
    findings = []
    parse_errors = []

    for label, path in CODE_FILES:
        tree, src_lines, err = parse_ast(path)
        audit_log.log(rid, "parse", {"file": label, "error": err})
        if err or tree is None:
            parse_errors.append((label, err))
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and not isinstance(node.value, bool):
                val = node.value
                if val in TRIVIAL:
                    continue
                matched = any(
                    (val == cv) or (isinstance(val, float) and abs(val - cv) < 1e-9)
                    for cv in config_numbers
                )
                if not matched:
                    findings.append((label, path, node.lineno, val))

    for label, path, lineno, val in findings:
        evidence.append(ev(path, lineno, commit))
        audit_log.log(rid, "const_not_in_config", {"file": label, "line": lineno, "value": val})

    n_sum = audit_log.log(
        rid, "scan_summary",
        {
            "code_files": [l for l, _ in CODE_FILES], "config_scanned": config_scanned,
            "config_missing": config_missing, "n_config_numbers": len(config_numbers), "n_findings": len(findings),
            "parse_errors": parse_errors,
        },
    )
    evidence.append(ev(audit_log.path, n_sum, commit))

    if parse_errors:
        return make_result(
            rid, "CẦN NGƯỜI XEM", evidence,
            f"[Chưa xác minh] Không phân tích được bằng ast.parse: {parse_errors}. Không đủ bằng chứng.",
        )

    if config_missing:
        return make_result(
            rid, "CẦN NGƯỜI XEM", evidence,
            f"[Chưa xác minh] Không đọc được config để đối chiếu: {config_missing}.",
        )

    if findings:
        detail = "; ".join(f"{l}:{ln} = {v!r}" for l, _, ln, v in findings[:20])
        return make_result(
            rid, "CẦN NGƯỜI XEM", evidence,
            f"ast.parse product/matching.py + product/pricing.py: {len(findings)} hằng số numeric (ngoài "
            f"{sorted(TRIVIAL)}) không khớp bất kỳ giá trị nào trong matching.json/pricing.json/mock_data.json: "
            f"{detail}{' ...' if len(findings) > 20 else ''}. Heuristic — có thể là chỉ số/độ dài hợp lệ, "
            f"cần người xem từng dòng để xác nhận có phải hằng số nghiệp vụ hay không.",
        )

    return make_result(
        rid, "ĐẠT", evidence,
        f"Quét toàn bộ ast.Constant numeric trong product/matching.py và product/pricing.py (loại trừ "
        f"{sorted(TRIVIAL)}), đối chiếu với {len(config_numbers)} giá trị số lấy từ "
        f"product/config/{{matching,pricing,mock_data}}.json: không có hằng số nào nằm ngoài config.",
    )

auditor/rules/m11_pricing_attr_independe:
"""
M11 - A.5.4 (pricing).
Quy tac: Gia phu thuoc thuoc tinh cua khach ngoai quang duong va thoi
diem. fare(distance_km, requested_at, config, logger=None) theo
INTERFACE.md chi nhan 2 thuoc tinh dau vao nghiep vu: distance_km,
requested_at.

Phan AST: quet product/pricing.py tim dau hieu doc du lieu khach ngoai
2 tham so cho phep - import/open/doc customers.json, hoac dinh danh
chua "segment"/"customer" (ca-insensitive, regex tren source text -
STATIC, khong phai doc hieu noi dung nghiep vu).

Phan thong ke (Phan ML don gian trong MATRIX_v0.md + chi dan rieng cho
M11 trong "Chi tiet quy tac" cua MATRIX_v0.md): chia chuyen theo phan vi
quantiles(distance_km, n=4) thanh 4 nhom quang duong tuong duong, trong
TUNG nhom so gia trung binh (fare_vnd) giua cac customer_segment, chenh
lech tuong doi >= 10% o bat ky nhom nao -> co thong ke.

Co thong ke CHI duoc day ket qua len CAN NGUOI XEM/KHONG DAT, khong bao
gio ha xuong DAT (chot MATRIX_v0.md).
"""
import ast
import re
import statistics
from common import make_result, ev, parse_ast, find_functions, load_json_file, repo_path

THRESHOLD = 0.10
SEGMENT_KEYWORD = re.compile(r"segment|customer", re.IGNORECASE)


def check(ctx):
    rid = "M11"
    commit = ctx["commit"]
    audit_log = ctx["audit_log"]
    run = ctx["run"]

    path = repo_path("product", "pricing.py")
    evidence = []

    # --- AST: cac tham so thuc te cua fare() ---
    tree, src_lines, err = parse_ast(path)
    audit_log.log(rid, "parse", {"file": "product/pricing.py", "error": err})
    param_issue = None
    if err or tree is None:
        param_issue = f"[Chưa xác minh] Không phân tích được product/pricing.py bằng ast.parse: {err}"
    else:
        fns = find_functions(tree, "fare")
        if not fns:
            param_issue = "[Chưa xác minh] Không tìm thấy hàm fare() trong product/pricing.py qua ast."
        else:
            fn = fns[0]
            arg_names = [a.arg for a in fn.args.args] + [a.arg for a in fn.args.kwonlyargs]
            allowed = {"distance_km", "requested_at", "config", "logger", "self"}
            extra = [a for a in arg_names if a not in allowed]
            if extra:
                evidence.append(ev(path, fn.lineno, commit))
                audit_log.log(rid, "extra_params", {"line": fn.lineno, "params": extra})
                param_issue = f"Hàm fare() nhận thêm tham số ngoài hợp đồng INTERFACE.md: {extra} (dòng {fn.lineno})."

    # --- quet tinh: dau hieu truy cap du lieu khach trong pricing.py ---
    keyword_hits = []
    io_hits = []
    try:
        with open(path, "r", encoding="utf-8") as f:
            lines = f.readlines()
        for i, line in enumerate(lines, start=1):
            if SEGMENT_KEYWORD.search(line):
                keyword_hits.append(i)
    except FileNotFoundError:
        lines = []

    if tree is not None:
        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                fname = None
                if isinstance(node.func, ast.Name):
                    fname = node.func.id
                elif isinstance(node.func, ast.Attribute):
                    fname = node.func.attr
                if fname in ("open", "load", "loads") :
                    io_hits.append(node.lineno)

    for ln in keyword_hits:
        evidence.append(ev(path, ln, commit))
        audit_log.log(rid, "keyword_hit", {"line": ln})
    for ln in io_hits:
        evidence.append(ev(path, ln, commit))
        audit_log.log(rid, "io_call", {"line": ln})

    code_flag = bool(keyword_hits) or bool(io_hits) or (param_issue is not None and "nhận thêm tham số" in (param_issue or ""))

    # --- thong ke theo quantile quang duong ---
    stat_flag = False
    stat_notes = []
    report_path = run.get("report_path")
    if report_path:
        data, text, rlines = load_json_file(report_path)
        results = data.get("results", [])
        dists = [r.get("distance_km") for r in results if isinstance(r.get("distance_km"), (int, float))]
        if len(dists) >= 8:
            try:
                qs = statistics.quantiles(dists, n=4)
            except Exception:
                qs = []
            if qs:
                def bucket(d):
                    for bi, q in enumerate(qs):
                        if d <= q:
                            return bi
                    return len(qs)

                buckets = {}
                for r in results:
                    d = r.get("distance_km")
                    seg = r.get("customer_segment")
                    fare = r.get("fare_vnd")
                    if not isinstance(d, (int, float)) or seg is None or not isinstance(fare, (int, float)):
                        continue
                    b = bucket(d)
                    buckets.setdefault(b, {}).setdefault(seg, []).append(fare)

                for b, seg_map in sorted(buckets.items()):
                    means = {seg: (sum(v) / len(v), len(v)) for seg, v in seg_map.items() if v}
                    if len(means) >= 2:
                        best = max(means, key=lambda s: means[s][0])
                        worst = min(means, key=lambda s: means[s][0])
                        bm, wm = means[best][0], means[worst][0]
                        rel = (bm - wm) / bm if bm > 0 else 0.0
                        if rel >= THRESHOLD:
                            stat_flag = True
                            stat_notes.append(
                                f"[Suy luận] Nhóm quãng đường #{b}: giá trung bình theo segment {means} — "
                                f"chênh lệch '{best}' vs '{worst}' = {rel:.2%} >= {THRESHOLD:.0%}."
                            )
                audit_log.log(rid, "quantile_stats", {"n_buckets": len(buckets), "stat_flag": stat_flag})
            else:
                stat_notes.append("[Chưa xác minh] Không tính được quantiles (statistics.quantiles lỗi hoặc rỗng).")
        else:
            stat_notes.append(f"[Chưa xác minh] Chỉ có {len(dists)} chuyến có distance_km hợp lệ — không đủ dữ liệu chia 4 nhóm phân vị đáng tin cậy.")
    else:
        stat_notes.append("[Chưa xác minh] Không có reports/product_run_<run_id>.json từ lần chạy fresh để thống kê.")

    n_sum = audit_log.log(
        rid, "scan_summary",
        {"param_issue": param_issue, "code_flag": code_flag, "stat_flag": stat_flag, "n_keyword_hits": len(keyword_hits), "n_io_hits": len(io_hits)},
    )
    evidence.append(ev(audit_log.path, n_sum, commit))

    if code_flag:
        return make_result(
            rid, "KHÔNG ĐẠT", evidence,
            f"ast.parse + quét regex product/pricing.py: {param_issue or ''} "
            f"Từ khoá segment/customer xuất hiện ở dòng {keyword_hits}; lời gọi open/load/loads ở dòng {io_hits}. "
            f"Đây là bằng chứng mã nguồn (không phải chỉ thống kê), cho thấy pricing có khả năng đọc dữ liệu/thuộc "
            f"tính khách ngoài distance_km, requested_at.",
        )

    if stat_flag:
        return make_result(
            rid, "CẦN NGƯỜI XEM", evidence,
            "Không tìm thấy dấu hiệu mã nguồn đọc thuộc tính khách ngoài hợp đồng (ast + regex sạch), nhưng cờ "
            "thống kê theo nhóm phân vị quãng đường (statistics.quantiles, n=4) vượt ngưỡng 10%: " + " ".join(stat_notes) +
            " Cờ thống kê không được dùng để tự kết luận KHÔNG ĐẠT (MATRIX_v0.md) — cần người xem xét.",
        )

    return make_result(
        rid, "ĐẠT", evidence,
        f"ast.parse fare() trong product/pricing.py: tham số đúng hợp đồng INTERFACE.md "
        f"(distance_km, requested_at, config, logger). Quét regex toàn file không thấy từ khoá "
        f"segment/customer, không có lời gọi open/load/loads. " + " ".join(stat_notes),
    )
